import os
import queue
import sys
import threading
from dataclasses import dataclass
from typing import Iterator, Optional

import pyaudio
from deepgram import DeepgramClient, LiveOptions, LiveTranscriptionEvents


@dataclass
class TranscriptEvent:
    text: str
    is_final: bool


class MicrophoneStream:
    def __init__(
        self,
        rate: int = 16000,
        chunk: int = 1024,
        channels: int = 1,
        format=pyaudio.paInt16,
    ):
        self.rate = rate
        self.chunk = chunk
        self.channels = channels
        self.format = format
        self._audio = pyaudio.PyAudio()
        self._stream = None
        self._buff: "queue.Queue[Optional[bytes]]" = queue.Queue()
        self._closed = True

    def __enter__(self):
        self._stream = self._audio.open(
            format=self.format,
            channels=self.channels,
            rate=self.rate,
            input=True,
            frames_per_buffer=self.chunk,
            stream_callback=self._callback,
        )
        self._closed = False
        self._stream.start_stream()
        return self

    def __exit__(self, exc_type, exc, tb):
        self._closed = True
        if self._stream is not None:
            self._stream.stop_stream()
            self._stream.close()
        self._buff.put(None)
        self._audio.terminate()

    def _callback(self, in_data, frame_count, time_info, status_flags):
        if self._closed:
            return (None, pyaudio.paComplete)
        self._buff.put(in_data)
        return (None, pyaudio.paContinue)

    def generator(self) -> Iterator[bytes]:
        while not self._closed:
            chunk = self._buff.get()
            if chunk is None:
                return
            yield chunk


def stream_microphone_transcripts() -> Iterator[TranscriptEvent]:
    api_key = os.getenv("DEEPGRAM_API_KEY")
    if not api_key:
        raise RuntimeError("DEEPGRAM_API_KEY is not set")

    dg_client = DeepgramClient(api_key)
    connection = dg_client.listen.websocket.v("1")

    transcript_queue: "queue.Queue[Optional[TranscriptEvent]]" = queue.Queue()
    finished = threading.Event()

    def on_message(self, result, **kwargs):
        try:
            sentence = result.channel.alternatives[0].transcript
            if not sentence:
                return
            is_final = bool(result.is_final)
            transcript_queue.put(TranscriptEvent(text=sentence, is_final=is_final))
        except Exception:
            pass

    def on_error(self, error, **kwargs):
        transcript_queue.put(None)
        finished.set()
        raise error

    def on_close(self, *args, **kwargs):
        transcript_queue.put(None)
        finished.set()

    connection.on(LiveTranscriptionEvents.Transcript, on_message)
    connection.on(LiveTranscriptionEvents.Error, on_error)
    connection.on(LiveTranscriptionEvents.Close, on_close)

    options = LiveOptions(
        model="nova-2",
        language="en-US",
        smart_format=True,
        interim_results=True,
        punctuate=True,
        encoding="linear16",
        sample_rate=16000,
        channels=1,
    )

    if not connection.start(options):
        raise RuntimeError("Failed to start Deepgram websocket connection")

    def audio_sender():
        try:
            with MicrophoneStream(rate=16000, chunk=1024, channels=1) as mic:
                for chunk in mic.generator():
                    if finished.is_set():
                        break
                    connection.send(chunk)
        finally:
            try:
                connection.finish()
            except Exception:
                pass

    sender_thread = threading.Thread(target=audio_sender, daemon=True)
    sender_thread.start()

    while not finished.is_set():
        item = transcript_queue.get()
        if item is None:
            break
        yield item

    sender_thread.join(timeout=2)


if __name__ == "__main__":
    try:
        for event in stream_microphone_transcripts():
            prefix = "[FINAL]" if event.is_final else "[INTERIM]"
            sys.stdout.write(f"\r{prefix} {event.text}        ")
            sys.stdout.flush()
            if event.is_final:
                sys.stdout.write("\n")
                sys.stdout.flush()
    except KeyboardInterrupt:
        pass
